import { styled } from '@hexa-ui/theme';

export const StyledInnovationPortfolioRoot = styled('div', {
  width: '100%',
});

export const StyledPieChartsRow = styled('div', {
  display: 'grid',
  width: '100%',
  minWidth: 0,
  boxSizing: 'border-box',
  gridTemplateColumns: 'repeat(3, minmax(0, 1fr))',
  alignItems: 'stretch',
  gap: '16px',
  marginTop: '16px',
  padding: '0 20px 20px 20px',
  '& > *': {
    minWidth: 0,
  },
});
